contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller provides an amount to fund this test contract
    // and then attempts to withdraw from c; the rule asserts that if c's balance becomes zero
    // after the withdraw call, then the caller must be the recorded Owner of c.
    function runTest(uint256 fundAmount) public payable {
        // make sure this test contract has enough balance to forward when needed
        require(address(this).balance >= fundAmount);

        // record Owner and pre-balance
        address owner = c.Owner();
        uint256 pre = address(c).balance;

        // fund C so there's something to withdraw
        if (fundAmount > 0) {
            // send funds to C via payable fallback/receive
            c.Command{value: fundAmount}(address(0), "");
        }

        // perform the withdraw call as msg.sender of this transaction
        c.withdraw{value: 0}();

        uint256 post = address(c).balance;

        // If the withdraw made the contract balance zero, then the caller must be Owner
        // (on the original P this holds because withdraw requires sender==Owner; mutant M removes that)
        assert(!(post == 0) || (msg.sender == owner));
    }

    // accept ETH so require(address(this).balance >= fundAmount) can be satisfied
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // call sequence: ensure this contract has enough ETH to fund a deposit into c,
    // then call Command or multiplicate not needed; only deposit via payable fallback of C
    // We'll send funds to c by calling payable address(c).call{value:amount}('') from this contract.

    receive() external payable {}

    // single public test function performing actions and final assert
    function runTest(uint256 depositAmount) public payable {
        // preconditions
        require(msg.value == 0, "do not send ETH to this call");
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= depositAmount, "this contract needs depositAmount balance");

        // Fund target contract c by sending ETH to it (triggers receive())
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "funding failed");

        // record balances before withdraw
        uint256 cBalanceBefore = address(c).balance;
        uint256 ownerAddrBalanceBefore = c.Owner();
        // ownerAddrBalanceBefore is an address but getter returns address; need its balance
        uint256 ownerBalanceBefore = address(ownerAddrBalanceBefore).balance;

        // call withdraw as Owner: this test contract must be Owner; ensure c.Owner() == address(this)
        require(c.Owner() == address(this), "test contract must be Owner of c");

        // perform withdraw (state-changing call must be top-level)
        c.withdraw{value:0}();

        // observe balances after withdraw
        uint256 cBalanceAfter = address(c).balance;
        uint256 ownerBalanceAfter = address(c.Owner()).balance;

        // GENERAL assertion: after withdraw the contract's balance becomes zero and Owner's balance increases by the previous contract balance
        // Expressed as: cBalanceAfter == 0 && ownerBalanceAfter >= ownerBalanceBefore + cBalanceBefore
        // Use single assert as required
        assert(cBalanceAfter == 0 && ownerBalanceAfter >= ownerBalanceBefore + cBalanceBefore);
    }
}

