    function run() public payable {
        // require that this test caller is the current Owner of c
        require(msg.sender == c.Owner());
        // ensure we have some Ether so the contract's balance can be non-zero and observable
        // send some ether to c first from this contract's balance if caller provided value
        require(address(this).balance >= 0);

        // record pre-call contract balance
        uint balBefore = address(c).balance;

        bool reverted;
        try c.withdraw{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // If the Owner called withdraw and it reverted, the contract balance must be unchanged.
        // Otherwise (no revert) we allow balance to change. This catches mutations that zero Owner before transfer
        // causing a revert that also moves funds (i.e., balance changed despite revert) in the mutant.
        assert(!reverted || balAfter == balBefore);
