        // caller of run is the test caller; to be Owner in P, the test must be deployed by Owner.
        // No extra precondition: require(true)
        require(true);

        // capture balance before
        uint balBefore = address(c).balance;

        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        uint balAfter = address(c).balance;

        // If the call reverted then the contract must not have been drained to zero (must remain > 0).
        // This captures that a revert should not coincide with the contract losing its funds (as in the mutant that sets Owner=address(0) then transfers, causing a revert while effectively attempting to drain).
        assert(!reverted || balAfter > 0 || balAfter == balBefore);
