import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // test runner account is address(this) by default in Foundry tests; record it
        deployer = address(this);
        c = new C();
    }

    // fuzzed parameters: target address to call and arbitrary bytes as calldata
    function testFuzz_property(address target, bytes calldata data, uint256 value) public {
        // keep domain wide but avoid trivial zero-value case if needed
        vm.assume(target != address(0));
        // fund the deployer and the contract so Command and subsequent possible withdraw can operate
        vm.deal(deployer, 1 ether);
        vm.deal(address(c), 1 ether);

        // If the target is a contract that reverts or transfers, we need to allow adversarial targets.
        // We deploy a helper attacker that will forward the call to target if target is this helper; otherwise
        // using the raw target address (EOA) is acceptable. The important part is that Command can be
        // invoked with any address; the property concerns Owner not changing as a result of Command.

        // Call Command from the Owner (deployer) with fuzzed params and fuzzed value
        vm.prank(deployer);
        // ensure deployer has the ether to attach
        uint256 sendValue = value % 1 ether; // keep within funded amount
        // execute Command: low-level call to target with data and attached value
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSelector(C.Command.selector, target, data));
        // We don't require the Command call to succeed; the invariant concerns Owner state regardless of success.

        // The general invariant: Owner should remain the original deployer address
        assertTrue(c.Owner() == deployer);
    }
}

