pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: attacker sends some wei and we fuzz a bytes payload
    function testFuzz_property(uint256 value, bytes memory data) public {
        // Keep value within reasonable bounds but allow zero as well
        value = bound(value, 0, 1 ether);

        // Deploy a helper that will revert when sent ETH (to model a failing callee)
        Reverter r = new Reverter();

        // Fund the helper so it has an address with non-zero balance (not required, but fine)
        vm.deal(address(this), 2 ether);

        // Prank the deployer (the default test contract seeded as msg.sender when c was created is this test contract)
        // The correct contract's Owner is the test contract (deployer). We'll call Command as Owner to forward value.
        vm.deal(address(this), value);
        vm.prank(address(this));
        // Call Command with the reverter's address and fuzzed data, attaching `value` wei
        // Use try/catch to avoid bubbling reverts into the test harness
        bool ok;
        try c.Command(address(r), data) payable returns (bytes memory) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: Owner is still the original deployer (this contract)
        // Read via public getter and assert once. For the correct contract this holds for all inputs.
        assertTrue(c.Owner() == address(this));
    }
}

// Helper that always reverts when called or sent ETH
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

