pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and a boolean toggle to decide whether attacker will call back
    function testFuzz_property(uint256 sendAmount, bool doReenter) public {
        // keep sendAmount in a reasonable range but wide
        sendAmount = bound(sendAmount, 1, 1 ether);

        // deploy attacker that will, when receiving Ether via call from c, optionally call c.withdraw()
        attacker = new Attacker(address(c));

        // fund the attacker so it can send in the initial Command call with value
        vm.deal(address(attacker), sendAmount);

        // craft calldata for attacker to receive and (optionally) call back into c.withdraw()
        // we'll encode doReenter so attacker knows whether to call withdraw in its fallback
        bytes memory data = abi.encode(doReenter);

        // have the attacker invoke c.Command(attacker, data) sending Ether
        vm.prank(address(attacker));
        // call Command on c with value sendAmount; attacker is the msg.sender
        // this will cause c to perform: attacker.call{value: msg.value}(data)
        // which will trigger attacker fallback and potentially call c.withdraw()
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Command.selector, address(attacker), data));
        // The above outer call should succeed for legitimate inputs; we don't assert on ok here

        // After the interaction, the correct contract preserves Owner != address(0)
        // single required assertion reading c's public getter Owner
        assertTrue(c.Owner() != address(0));
    }
}

// Attacker contract: when called with {value}, it decodes the calldata (a bool) and if true
// it will call back into c.withdraw(); this models an external callee that triggers withdraw
// during the external call from c, which exposes the mutant's zeroing-before-transfer bug.
contract Attacker {
    address public target;
    bool public lastFlag;
    constructor(address _t) payable {
        target = _t;
    }
    receive() external payable {
        // nothing: Command will use call with data, so fallback may not be used
    }
    fallback() external payable {
        // decode the bool flag from calldata; default false if malformed
        bool flag = false;
        if (msg.data.length >= 32) {
            flag = abi.decode(msg.data, (bool));
        }
        lastFlag = flag;
        if (flag) {
            // call withdraw() on target to trigger the sequence that the mutant mishandles
            // send no value
            (bool ok, ) = target.call(abi.encodeWithSelector(C.withdraw.selector));
            // ignore success — we model adversarial behaviour
            ok;
        }
    }
}

