pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send to Command, and a flag to pick whether the helper will call back
    function testFuzz_property(uint256 amount, bool doCallBack) public {
        // keep amount in a sensible wide range but allow zero too
        amount = bound(amount, 0, 1 ether);

        // deploy adversarial helper that on receiving Ether optionally calls c.withdraw()
        AttackerHelper h = new AttackerHelper(address(c));

        // fund the attacker helper so it can perform any call if needed
        vm.deal(address(h), 0);

        // ensure owner (deployer) has funds to send via Command
        address deployer = address(this);
        vm.deal(deployer, amount + 1);

        // If doCallBack true, configure helper to call back into c.withdraw during its fallback
        h.setShouldCallBack(doCallBack);

        // call Command with helper as callee and attach value amount
        vm.prank(deployer);
        // craft arbitrary calldata (empty is fine)
        bytes memory data = "";
        // perform the call which will send Ether to helper; helper's fallback may call c.withdraw()
        c.Command{value: amount}(address(h), data);

        // Single assertion: after this interaction, the correct contract preserves Owner == deployer
        // (the reference should satisfy this for all inputs; the mutant can violate it for some inputs)
        assertTrue(c.Owner() == address(this));
    }
}

// Helper that on receiving Ether optionally calls back into c.withdraw()
contract AttackerHelper {
    address public target;
    bool public shouldCallBack;
    constructor(address _target) payable {
        target = _target;
        shouldCallBack = false;
    }
    function setShouldCallBack(bool v) public {
        shouldCallBack = v;
    }
    receive() external payable {
        if (shouldCallBack) {
            // call withdraw on target; use low-level call to avoid revert bubbling
            (bool ok, ) = target.call(abi.encodeWithSignature("withdraw()"));
            // ignore ok
            ok;
        }
    }
}

