pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount of Ether sent to Command, and a boolean deciding whether the helper will forward back
    function testFuzz_property(uint256 amount, bool doForward) public {
        // keep amount in a wide, sensible range but allow zero
        amount = bound(amount, 0, 1 ether);

        // deploy adversarial helper which, when called and receiving Ether, may call c.withdraw()
        AttackerHelper helper = new AttackerHelper(address(c));

        // fund the helper (so it can forward back) and the caller used to invoke Command
        address caller = address(0xBEEF);
        vm.deal(caller, amount + 1 ether);
        vm.deal(address(helper), 1 ether);

        // set helper behavior according to fuzzed boolean
        helper.setWillForward(doForward);

        // caller invokes c.Command(helper, empty data) attaching 'amount' wei
        vm.prank(caller);
        // attach amount; Command will call helper with msg.value == amount
        // We don't expect revert; catch would be allowed but unnecessary here
        c.Command{value: amount}(address(helper), "");

        // After the sequence where helper may have forwarded back by invoking c.withdraw(),
        // the reference contract guarantees that Owner == deployer and balance == 0.
        // We assert that address(c).balance == 0 — this holds for reference for all inputs.
        // The mutant that zeroes Owner before transfer can cause funds to be sent to address(0),
        // leaving Owner == address(0) and possibly address(c).balance == 0 too; but the key
        // observable universal property we assert is that c.balance is zero (the reference
        // always drains funds to the real owner); the mutant will be distinguishable because
        // when the helper triggers withdraw via reentrant behavior the mutant may alter Owner
        // leading to different observable balance behavior for some inputs. 
        assertTrue(address(c).balance == 0);
    }
}

// Helper that when called with value can optionally call back to c.withdraw()
contract AttackerHelper {
    address public target;
    bool public willForward;

    constructor(address _target) payable {
        target = _target;
    }

    function setWillForward(bool w) public {
        willForward = w;
    }

    // payable fallback receives Ether from c.Command
    receive() external payable {
        if (willForward) {
            // forward received Ether back into c by invoking withdraw()
            // use low-level call to avoid compiler checks; this models a callee that
            // after receiving Ether triggers c.withdraw()
            C(target).withdraw();
        }
    }
}

