pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller (address) and deposit amount
    function testFuzz_property(address caller, uint256 deposit) public {
        // keep deposit within reasonable bounds but wide
        deposit = bound(deposit, 0, 1 ether);

        // ensure the fuzzer may choose a caller different from the contract Owner
        // Owner is the deployer (this test contract), so let caller be any address

        // fund caller so they can send value
        vm.deal(caller, deposit + 1 wei);

        // have caller send Ether to the contract (to create non-zero balance)
        if (deposit > 0) {
            vm.prank(caller);
            (bool s, ) = address(c).call{value: deposit}("");
            require(s);
        }

        // Now call withdraw as the stored Owner (the deployer of C is this test contract)
        // The correct contract sends the full balance to Owner, leaving address(c).balance == 0
        // The mutant sends to msg.sender (which will be the test contract here) and still leaves balance == 0
        // To expose the mutant, we must call withdraw as a different caller than Owner so that require(msg.sender==Owner) fails
        // But require prevents the call; instead the distinguishing behavior is when Owner != msg.sender but the require passes
        // That occurs only if Owner == msg.sender. To trigger the mutant difference, we simulate the scenario where Owner is an EOA
        // different from the caller: the reference sends to stored Owner while mutant sends to caller; so we call withdraw as Owner.

        // Owner of c is msg.sender at deployment: setUp deployed c with this test contract as Owner.
        // So to exercise the function legitimately, the caller must be this test contract.

        // Call withdraw as the Owner (this contract). Before calling, ensure c has some balance.
        // If deposit was zero, send a tiny amount from this contract to c so contract has balance.
        if (address(c).balance == 0) {
            // fund this test contract
            vm.deal(address(this), 1 wei);
            // send 1 wei to c
            (bool s2, ) = address(c).call{value: 1 wei}("");
            require(s2);
        }

        // record balance before withdraw
        uint256 balBefore = address(c).balance;
        // call withdraw as Owner (this contract)
        // it may revert, capture success
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: when Owner calls withdraw successfully, the contract balance becomes zero.
        // So assert that if the call succeeded, address(c).balance == 0
        assertTrue(!ok || address(c).balance == 0);
    }
}
